function texture(kind){const c=document.createElement('canvas');c.width=c.height=512;const ctx=c.getContext('2d');let seed=98765;const rand=()=>{seed=(1664525*seed+1013904223)>>>0;return seed/4294967296;};if(kind==='wood'){for(let y=0;y<512;y+=32){const baseR=175+Math.floor(rand()*25),baseG=130+Math.floor(rand()*20),baseB=85+Math.floor(rand()*18);ctx.fillStyle='rgb('+baseR+','+baseG+','+baseB+')';ctx.fillRect(0,y,512,31);ctx.fillStyle='rgba(45,30,15,0.55)';ctx.fillRect(0,y+31,512,1);for(let x=0;x<512;x+=128){const xx=x+(y%64?64:0);ctx.fillRect(xx,y,1.5,31);}ctx.strokeStyle='rgba(60,40,20,0.12)';for(let k=0;k<60;k++){const yy=y+rand()*30;ctx.beginPath();ctx.moveTo(rand()*512,yy);ctx.lineTo(rand()*512,yy+0.5);ctx.stroke();}}}else if(kind==='grass'){ctx.fillStyle='#449826';ctx.fillRect(0,0,512,512);for(let i=0;i<4000;i++){ctx.fillStyle='rgba(35,78,22,'+(0.15+rand()*0.25)+')';ctx.fillRect(rand()*512,rand()*512,4+rand()*8,4+rand()*8);}for(let i=0;i<26000;i++){const tone=rand();ctx.fillStyle=tone>0.65?'rgba(110,198,52,'+(0.35+rand()*0.45)+')':(tone>0.3?'rgba(82,165,40,'+(0.3+rand()*0.4)+')':'rgba(55,120,30,'+(0.25+rand()*0.35)+')');ctx.fillRect(rand()*512,rand()*512,1+rand()*1.6,2+rand()*4.5);}for(let i=0;i<5000;i++){ctx.fillStyle='rgba(195,225,85,'+(0.2+rand()*0.3)+')';ctx.fillRect(rand()*512,rand()*512,1,2);}}else if(kind==='paving'){ctx.fillStyle='#ede5d5';ctx.fillRect(0,0,512,512);for(let ty=0;ty<512;ty+=64){for(let tx=0;tx<512;tx+=64){const v=Math.floor((rand()-0.5)*18);ctx.fillStyle='rgba('+(v>0?255:40)+','+(v>0?250:35)+','+(v>0?235:30)+','+(Math.abs(v)/255*0.35)+')';ctx.fillRect(tx,ty,64,64);}}for(let i=0;i<12000;i++){const cval=Math.floor(rand()*70);ctx.fillStyle='rgba('+cval+','+cval+','+cval+','+(0.04+rand()*0.1)+')';ctx.fillRect(rand()*512,rand()*512,1+rand()*2,1+rand()*2);}ctx.strokeStyle='rgba(110,100,85,0.4)';ctx.lineWidth=2;for(let i=0;i<=512;i+=64){ctx.beginPath();ctx.moveTo(i,0);ctx.lineTo(i,512);ctx.stroke();ctx.beginPath();ctx.moveTo(0,i);ctx.lineTo(512,i);ctx.stroke();}}else if(kind==='asphalt'){ctx.fillStyle='#2c323c';ctx.fillRect(0,0,512,512);for(let i=0;i<32000;i++){const g=55+Math.floor(rand()*55);ctx.fillStyle='rgba('+g+','+(g+4)+','+(g+8)+','+(0.15+rand()*0.3)+')';ctx.fillRect(rand()*512,rand()*512,1+rand()*2,1+rand()*2);}for(let i=0;i<6000;i++){ctx.fillStyle='rgba(210,220,230,'+(0.1+rand()*0.15)+')';ctx.fillRect(rand()*512,rand()*512,1,1);}}else if(kind==='fabric'){ctx.fillStyle='#b8b19c';ctx.fillRect(0,0,512,512);ctx.strokeStyle='rgba(40,35,25,0.15)';for(let i=0;i<512;i+=4){ctx.beginPath();ctx.moveTo(i,0);ctx.lineTo(i,512);ctx.stroke();ctx.beginPath();ctx.moveTo(0,i);ctx.lineTo(512,i);ctx.stroke();}}else if(kind==='soil'){ctx.fillStyle='#4a331e';ctx.fillRect(0,0,512,512);for(let y=0;y<512;y+=16){ctx.fillStyle=rand()>0.5?'rgba(42,26,14,0.45)':'rgba(88,60,36,0.35)';ctx.fillRect(0,y,512,8+Math.floor(rand()*4));}for(let i=0;i<18000;i++){const tone=rand();ctx.fillStyle=tone>0.7?'rgba(98,68,40,'+(0.25+rand()*0.35)+')':tone>0.35?'rgba(38,24,12,'+(0.3+rand()*0.4)+')':'rgba(120,84,50,'+(0.18+rand()*0.25)+')';ctx.fillRect(rand()*512,rand()*512,1.5+rand()*3.5,1.5+rand()*2.5);}for(let i=0;i<10000;i++){ctx.fillStyle='rgba(25,15,8,'+(0.15+rand()*0.25)+')';ctx.fillRect(rand()*512,rand()*512,1+rand()*1.5,1+rand()*1.5);}for(let i=0;i<3000;i++){ctx.fillStyle='rgba(142,88,48,'+(0.15+rand()*0.2)+')';ctx.fillRect(rand()*512,rand()*512,1,1);}}else if(kind==='crop'){ctx.fillStyle='#2f681a';ctx.fillRect(0,0,512,512);for(let y=0;y<512;y+=12){ctx.fillStyle='rgba(26,56,14,0.42)';ctx.fillRect(0,y+8,512,4);ctx.fillStyle='rgba(65,138,34,0.48)';ctx.fillRect(0,y,512,8);}for(let i=0;i<24000;i++){const tone=rand();ctx.fillStyle=tone>0.65?'rgba(92,185,42,'+(0.35+rand()*0.45)+')':tone>0.3?'rgba(56,128,26,'+(0.3+rand()*0.4)+')':'rgba(38,88,18,'+(0.3+rand()*0.35)+')';ctx.fillRect(rand()*512,rand()*512,1.5+rand()*2.2,2+rand()*4.0);}for(let i=0;i<6000;i++){ctx.fillStyle='rgba(154,228,68,'+(0.22+rand()*0.35)+')';ctx.fillRect(rand()*512,rand()*512,1.2+rand()*1.8,1.5+rand()*2.0);}for(let i=0;i<4000;i++){ctx.fillStyle='rgba(48,32,18,'+(0.2+rand()*0.3)+')';ctx.fillRect(rand()*512,rand()*512,1.5+rand()*2,1.5+rand()*2);}}const t=new THREE.CanvasTexture(c);t.wrapS=t.wrapT=THREE.RepeatWrapping;t.repeat.set(kind==='wood'?4:kind==='grass'?8:kind==='soil'?10:kind==='crop'?10:6,kind==='wood'?5:kind==='grass'?8:kind==='soil'?10:kind==='crop'?10:6);t.anisotropy=Math.min(8,renderer.capabilities.getMaxAnisotropy());return t;}
