// =========================================================================
// ROAD INFRASTRUCTURE: UTILITY POLES, STREET LIGHTS & OVERHEAD WIRES (TAAR)
// In front of the Main Gate (Assan-Thirana Road) and along the Helipad Road
// =========================================================================
function buildRoadInfrastructure(targetScene) {
  const infraGroup = new THREE.Group();
  infraGroup.name = 'roadInfrastructureGroup';
  infraGroup.userData = {
    streetLights: [],
    lightCones: [],
    ledLensMat: null
  };

  // Materials
  const poleMat = new THREE.MeshStandardMaterial({ color: 0x64748b, roughness: 0.78, metalness: 0.25 });
  const baseMat = new THREE.MeshStandardMaterial({ color: 0x94a3b8, roughness: 0.88, metalness: 0.10 });
  const metalMat = new THREE.MeshStandardMaterial({ color: 0x334155, roughness: 0.35, metalness: 0.85 });
  const insulMat = new THREE.MeshStandardMaterial({ color: 0xe0f2fe, roughness: 0.15, metalness: 0.10 });
  const lampBodyMat = new THREE.MeshStandardMaterial({ color: 0x1e293b, roughness: 0.40, metalness: 0.75 });
  const ledLensMat = new THREE.MeshStandardMaterial({
    color: 0xfffaed,
    emissive: 0xfff3cc,
    emissiveIntensity: 3.6,
    roughness: 0.15
  });
  infraGroup.userData.ledLensMat = ledLensMat;
  const wireMat = new THREE.MeshStandardMaterial({ color: 0x18181b, roughness: 0.65, metalness: 0.45 });
  const lightConeMat = new THREE.MeshBasicMaterial({
    color: 0xfff6dd,
    transparent: true,
    opacity: 0.14,
    side: THREE.DoubleSide,
    depthWrite: false
  });

  // Reusable Geometries
  const baseGeo = new THREE.CylinderGeometry(0.25, 0.32, 0.45, 12);
  const poleGeo = new THREE.CylinderGeometry(0.10, 0.16, 7.2, 12);
  const crossarmGeo = new THREE.BoxGeometry(1.8, 0.08, 0.08);
  const braceGeo = new THREE.BoxGeometry(0.04, 0.6, 0.04);
  const insulGeo = new THREE.CylinderGeometry(0.04, 0.065, 0.16, 8);
  const armGeo = new THREE.CylinderGeometry(0.03, 0.038, 2.0, 8);
  const lampGeo = new THREE.BoxGeometry(0.28, 0.12, 0.65);
  const lensGeo = new THREE.PlaneGeometry(0.22, 0.52);
  const coneGeo = new THREE.ConeGeometry(4.6, 5.8, 16, 1, true);
  coneGeo.translate(0, -2.9, 0);

  // Surface elevation helper (robust fallback)
  function getGroundY(x, z) {
    if (typeof vrSurface === 'function') {
      try { return vrSurface(x, z, 0.12); } catch (e) {}
    }
    return 0.12;
  }

  // 1. Definition of Pole Locations and Street Light Outreach Directions
  // Main Road line (highway directly in front of main gate [-12.77, -65.07])
  const mainPoles = [
    { p: [-75.0, -74.0], roadDir: [0, 1] },
    { p: [-54.0, -77.5], roadDir: [0, 1] },
    { p: [-33.0, -81.0], roadDir: [0, 1] },
    { p: [-12.5, -84.5], roadDir: [0, 1] }, // Directly opposite Main Gate!
    { p: [8.5, -88.0],   roadDir: [0, 1] }, // Road junction
    { p: [29.5, -91.5],  roadDir: [0, 1] }  // East continuation
  ];

  // Helipad Access Road (connects from main road junction all the way to circular helipad)
  const helipadPoles = [
    { p: [8.5, -88.0],   roadDir: [0, 1] },  // Junction anchor
    { p: [13.5, -96.0],  roadDir: [-1, 0] },
    { p: [15.5, -119.0], roadDir: [-1, 0] },
    { p: [17.5, -142.0], roadDir: [-1, 0] }, // Approaching helipad gate
    { p: [19.8, -165.0], roadDir: [-1, 0] }, // Past gate
    { p: [20.0, -189.0], roadDir: [-1, 0] },
    { p: [20.2, -213.0], roadDir: [-1, 0] },
    { p: [20.4, -237.0], roadDir: [-1, 0] },
    { p: [20.6, -261.0], roadDir: [-1, 0] },
    { p: [20.8, -284.0], roadDir: [-1, 0] }, // North bend
    { p: [9.5, -293.0],  roadDir: [0, 1] },  // Curving west towards helipad
    { p: [-2.0, -293.5], roadDir: [0, 1] }   // Circular Helipad apron perimeter
  ];

  // Store computed attachment points for wire catenaries
  const poleAttachmentPoints = new Map();

  function createPole(item, index, prefix) {
    const key = prefix + '_' + index;
    const px = item.p[0];
    const pz = item.p[1];
    const py = getGroundY(px, pz);

    const poleGroup = new THREE.Group();
    poleGroup.position.set(px, py, pz);

    // Concrete base foundation
    const base = new THREE.Mesh(baseGeo, baseMat);
    base.position.y = 0.225;
    poleGroup.add(base);

    // Tapered pole shaft
    const shaft = new THREE.Mesh(poleGeo, poleMat);
    shaft.position.y = 3.8;
    poleGroup.add(shaft);

    // Orientation angle for outreach arm and crossarm
    const rdx = item.roadDir[0];
    const rdz = item.roadDir[1];
    const roadAngle = Math.atan2(rdx, rdz); // angle pointing towards the road

    // Crossarm (T-bar) perpendicular to road/wire flow (angle = roadAngle + PI/2)
    const crossarmAngle = roadAngle + Math.PI / 2;
    const crossarmGroup = new THREE.Group();
    crossarmGroup.position.y = 7.0;
    crossarmGroup.rotation.y = crossarmAngle;

    const crossarm = new THREE.Mesh(crossarmGeo, metalMat);
    crossarmGroup.add(crossarm);

    // Diagonal braces
    for (const bSide of [-0.45, 0.45]) {
      const brace = new THREE.Mesh(braceGeo, metalMat);
      brace.position.set(bSide * 0.7, -0.28, 0);
      brace.rotation.z = (bSide < 0 ? 1 : -1) * 0.65;
      crossarmGroup.add(brace);
    }

    // 3 Insulators on crossarm (Left, Center, Right)
    const insulOffsets = [-0.72, 0.0, 0.72];
    const worldInsulators = [];

    for (let oIdx = 0; oIdx < insulOffsets.length; oIdx++) {
      const insX = insulOffsets[oIdx];
      const ins = new THREE.Mesh(insulGeo, insulMat);
      ins.position.set(insX, 0.12, 0);
      crossarmGroup.add(ins);

      // Compute world position for wire connection
      const localVec = new THREE.Vector3(insX, 0.20, 0);
      localVec.applyAxisAngle(new THREE.Vector3(0, 1, 0), crossarmAngle);
      worldInsulators.push(new THREE.Vector3(px + localVec.x, py + 7.0 + localVec.y, pz + localVec.z));
    }
    poleGroup.add(crossarmGroup);

    // Top pin insulator on pole tip for earth / lightning wire
    const topIns = new THREE.Mesh(insulGeo, insulMat);
    topIns.position.set(0, 7.48, 0);
    poleGroup.add(topIns);
    const worldTopPin = new THREE.Vector3(px, py + 7.56, pz);

    // Save connection anchor points
    poleAttachmentPoints.set(key, {
      left: worldInsulators[0],
      center: worldInsulators[1],
      right: worldInsulators[2],
      top: worldTopPin
    });

    // Street Light Outreach Bracket Arm & Luminaire
    const armGroup = new THREE.Group();
    armGroup.position.y = 6.35;
    armGroup.rotation.y = roadAngle;

    // Angled cantilever outreach arm reaching out over the road
    const arm = new THREE.Mesh(armGeo, metalMat);
    arm.rotation.x = Math.PI / 2.35;
    arm.position.set(0, 0.18, 0.95);
    armGroup.add(arm);

    // Luminaire casing (cobra-head style)
    const lamp = new THREE.Mesh(lampGeo, lampBodyMat);
    lamp.position.set(0, 0.42, 1.95);
    lamp.rotation.x = -0.15; // slightly angled downwards towards road center
    armGroup.add(lamp);

    // Glowing LED emission face
    const lens = new THREE.Mesh(lensGeo, ledLensMat);
    lens.rotation.x = Math.PI / 2 - 0.15;
    lens.position.set(0, 0.355, 1.95);
    armGroup.add(lens);

    // Downward soft atmospheric light cone onto road
    const cone = new THREE.Mesh(coneGeo, lightConeMat);
    cone.position.set(0, 0.35, 1.95);
    armGroup.add(cone);
    infraGroup.userData.lightCones.push(cone);

    // Authentic roadside point light illumination
    const streetLight = new THREE.PointLight(0xfffae6, 0.65, 22, 1.25);
    streetLight.position.set(0, 0.25, 1.95);
    armGroup.add(streetLight);
    infraGroup.userData.streetLights.push(streetLight);

    poleGroup.add(armGroup);
    infraGroup.add(poleGroup);
  }

  // Build Main Road Poles
  mainPoles.forEach((item, i) => createPole(item, i, 'main'));

  // Build Helipad Road Poles (skip index 0 as it shares the junction pole)
  for (let i = 1; i < helipadPoles.length; i++) {
    createPole(helipadPoles[i], i, 'heli');
  }

  // 2. Build Continuous Overhead Catenary Wires (Taar)
  function createWireSpan(pA, pB, sagDepth) {
    const dist = pA.distanceTo(pB);
    const sag = sagDepth || Math.max(0.25, dist * 0.016);
    const curvePoints = [];
    const segments = 8;
    for (let k = 0; k <= segments; k++) {
      const t = k / segments;
      const x = pA.x + (pB.x - pA.x) * t;
      const z = pA.z + (pB.z - pA.z) * t;
      const yLinear = pA.y + (pB.y - pA.y) * t;
      const ySag = 4.0 * sag * t * (1.0 - t); // Parabolic catenary sag formula
      curvePoints.push(new THREE.Vector3(x, yLinear - ySag, z));
    }
    const curve = new THREE.CatmullRomCurve3(curvePoints);
    const tubeGeo = new THREE.TubeGeometry(curve, 10, 0.016, 5, false);
    return new THREE.Mesh(tubeGeo, wireMat);
  }

  function connectPoles(keyA, keyB) {
    const a = poleAttachmentPoints.get(keyA);
    const b = poleAttachmentPoints.get(keyB);
    if (!a || !b) return;

    // 4 Parallel Overhead Lines: Left, Center, Right, and Top Earth wire
    infraGroup.add(createWireSpan(a.left, b.left, 0.36));
    infraGroup.add(createWireSpan(a.center, b.center, 0.38));
    infraGroup.add(createWireSpan(a.right, b.right, 0.36));
    infraGroup.add(createWireSpan(a.top, b.top, 0.28));
  }

  // Connect Main Road Pole Wires
  for (let i = 0; i < mainPoles.length - 1; i++) {
    connectPoles('main_' + i, 'main_' + (i + 1));
  }

  // Connect Junction Pole (main_4: [8.5, -88.0]) to First Helipad Pole (heli_1: [13.5, -96.0])
  connectPoles('main_4', 'heli_1');

  // Connect Helipad Road Pole Wires
  for (let i = 1; i < helipadPoles.length - 1; i++) {
    connectPoles('heli_' + i, 'heli_' + (i + 1));
  }

  targetScene.add(infraGroup);
  return infraGroup;
}

