function handleFreeCameraFlight(e){
  if(['SELECT','INPUT','TEXTAREA'].includes(e.target.tagName)||e.target.isContentEditable)return;
  if(window.__DEP_IS_OFFICER_SELECTED&&window.__DEP_IS_OFFICER_SELECTED())return;
  const dist=camera.position.distanceTo(controls.target),panSpeed=(e.shiftKey?2.4:1.2)*Math.max(0.4,dist*0.018);
  const k=(e.key||'').toLowerCase();
  if(k==='arrowleft'||k==='a'){camVelocity.panRight-=panSpeed;e.preventDefault();}
  else if(k==='arrowright'||k==='d'){camVelocity.panRight+=panSpeed;e.preventDefault();}
  else if(k==='arrowup'||k==='w'){camVelocity.panForward+=panSpeed;e.preventDefault();}
  else if(k==='arrowdown'||k==='s'){camVelocity.panForward-=panSpeed;e.preventDefault();}
  else if(k==='+'||k==='='){camVelocity.zoom-=0.045;e.preventDefault();}
  else if(k==='-'){camVelocity.zoom+=0.045;e.preventDefault();}
}
window.addEventListener('keydown',handleFreeCameraFlight);
root.addEventListener('keydown',handleFreeCameraFlight);
